function MedicalTable({title,add,onAdd,headers,rows,empty}:{title:string;add:string;onAdd:()=>void;headers:string[];rows:string[][];empty:string}){return <section className="panel table-panel"><div className="panel-header"><div><h2>{title}</h2></div><button className="primary-btn" onClick={onAdd}>{add}</button></div><TableWrap><table><thead><tr>{headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{r.map((v,j)=><td key={j}>{v||'—'}</td>)}</tr>)}{!rows.length&&<EmptyRow col={headers.length} text={empty}/>}</tbody></table></TableWrap></section>}
