function Reports({employees,punches,leaves,missions,penalties,balances,settings}:{employees:Employee[];punches:Punch[];leaves:Leave[];missions:Mission[];penalties:Penalty[];balances:LeaveBalance[];settings:any}){const [month,setMonth]=useState(today().slice(0,7));const [from,setFrom]=useState(today()),[to,setTo]=useState(today()),[dept,setDept]=useState('الكل'),[empId,setEmpId]=useState('الكل');const inRange=(d:string)=>d>=from&&d<=to;const empFilter=(id:number)=>empId==='الكل'||id===Number(empId);const empRows=employees.filter(e=>(dept==='الكل'||e.department===dept)&&empFilter(e.id));const attendanceRange=punches.filter(x=>inRange(x.date)&&empRows.some(e=>e.code===x.code));const leavesRange=leaves.filter(x=>(inRange(x.from)||inRange(x.to)||(x.from<from&&x.to>to))&&empFilter(x.employeeId));const missionsRange=missions.filter(x=>(inRange(x.from)||inRange(x.to)||(x.from<from&&x.to>to))&&empFilter(x.employeeId));const penaltiesRange=penalties.filter(x=>inRange(x.date)&&empFilter(x.employeeId));function leaveBalanceReport(){const y=month.slice(0,4);return empRows.map(e=>{const b=balances.find(x=>x.employeeId===e.id&&x.year===y)||{employeeId:e.id,year:y,annual:30,casual:7};const used=(type:string)=>leaves.filter(x=>x.employeeId===e.id&&x.status==='معتمدة'&&x.type===type).reduce((s,x)=>{const ys=y+'-01-01',ye=y+'-12-31',a=x.from>ys?x.from:ys,z=x.to<ye?x.to:ye;return s+(a<=z?daysBetween(a,z):0)},0);const au=used('اعتيادية'),cu=used('عارضة');return {الرقم:e.code,الاسم:e.name,القسم:e.department,اعتيادي_مستحق:b.annual,اعتيادي_مستخدم:au,اعتيادي_متبقي:b.annual-au,عارضة_مستحق:b.casual,عارضة_مستخدمة:cu,عارضة_متبقية:b.casual-cu}})}function attendanceSummary(){return empRows.map(e=>{const ps=attendanceRange.filter(p=>p.code===e.code),days=new Set(ps.map(p=>p.date)),single=new Set(ps.filter(p=>ps.filter(z=>z.date===p.date).length===1).map(p=>p.date));return {الرقم:e.code,الاسم:e.name,القسم:e.department,أيام_الحضور:days.size,بصمة_واحدة:single.size,عدد_البصمات:ps.length}})}function lateReport(){const start=settings.start||'08:30';const grace=Number(settings.grace||0);const [h,m]=start.split(':').map(Number);const total=h*60+m+grace;const threshold=String(Math.floor(total/60)).padStart(2,'0')+':'+String(total%60).padStart(2,'0');return empRows.map(e=>{const ps=attendanceRange.filter(p=>p.code===e.code),late=ps.filter(p=>p.time>threshold);return {الرقم:e.code,الاسم:e.name,القسم:e.department,بداية_العمل:start,سماح_التأخير:grace,حد_التأخير:threshold,مرات_التأخير:late.length,أيام_الحضور:new Set(ps.map(p=>p.date)).size}}).filter(x=>x.مرات_التأخير>0)}function monthlyMatrix(){const [y,m]=month.split('-').map(Number),days=new Date(y,m,0).getDate(),holidays=String(settings.holidays||'').split(/[\n,]+/).map(x=>x.trim()).filter(Boolean);return empRows.map(e=>{const row:any={الرقم:e.code,الاسم:e.name,القسم:e.department};for(let d=1;d<=days;d++){const ds=month+'-'+String(d).padStart(2,'0'),ps=punches.filter(x=>x.code===e.code&&x.date===ds),lv=leaves.find(x=>x.employeeId===e.id&&x.status==='معتمدة'&&x.from<=ds&&x.to>=ds),dow=new Date(ds+'T00:00:00').getDay();row['يوم '+d]=holidays.includes(ds)?'ع':(settings.fridayOff&&dow===5)?'ج':lv?'إ':ps.length?(ps.length===1?'1':'✓'):'غ'}return row})}return <><PageActions title="التقارير" text="مركز التقارير — تصفية حسب الفترة والقسم والموظف والتصدير إلى Excel" action="📥 الموظفين" onClick={()=>excel(empRows,'employees.xlsx')}/><section className="stats"><Stat icon="👥" label="الموظفون" value={empRows.length}/><Stat icon="🕘" label="بصمات الفترة" value={attendanceRange.length}/><Stat icon="🏖️" label="إجازات الفترة" value={leavesRange.length}/><Stat icon="📋" label="مأموريات الفترة" value={missionsRange.length}/><Stat icon="⚠️" label="جزاءات الفترة" value={penaltiesRange.length}/></section><section className="panel"><div className="toolbar"><label>من <input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>إلى <input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label><label>القسم <select value={dept} onChange={e=>{setDept(e.target.value);setEmpId('الكل')}}><option>الكل</option><option>فني</option><option>تجاري</option><option>نظم</option><option>إداري</option></select></label><label>الموظف <select value={empId} onChange={e=>setEmpId(e.target.value)}><option value="الكل">الكل</option>{employees.filter(e=>dept==='الكل'||e.department===dept).map(e=><option key={e.id} value={e.id}>{e.name}</option>)}</select></label><label>شهر الحضور <input type="month" value={month} onChange={e=>setMonth(e.target.value)}/></label></div><div className="actions report-actions"><button onClick={()=>excel(empRows,'employees.xlsx')}>👥 الموظفين</button><button onClick={()=>excel(attendanceRange,'attendance-range.xlsx')}>🕘 بصمات الفترة</button><button onClick={()=>excel(attendanceSummary(),'attendance-summary.xlsx')}>📊 ملخص الحضور</button><button onClick={()=>excel(lateReport(),'late-report.xlsx')}>⏱ تقرير التأخير</button><button onClick={()=>excel(monthlyMatrix(),'attendance-'+month+'.xlsx')}>📅 مصفوفة الحضور الشهرية</button><button onClick={()=>excel(leavesRange,'leaves-range.xlsx')}>🏖️ الإجازات</button><button onClick={()=>excel(leaveBalanceReport(),'leave-balances-'+month.slice(0,4)+'.xlsx')}>🏖️ أرصدة الإجازات</button><button onClick={()=>excel(missionsRange,'missions-range.xlsx')}>📋 المأموريات</button><button onClick={()=>excel(penaltiesRange,'penalties-range.xlsx')}>⚠️ الجزاءات</button></div></section><section className="panel"><div className="panel-header"><div><h2>ملخص الحضور</h2><p>حسب الموظف ضمن الفترة المحددة</p></div></div><TableWrap><table><thead><tr><th>الرقم</th><th>الاسم</th><th>القسم</th><th>أيام الحضور</th><th>بصمة واحدة</th><th>إجمالي البصمات</th></tr></thead><tbody>{attendanceSummary().map(x=><tr key={x.الرقم}><td>{x.الرقم}</td><td>{x.الاسم}</td><td>{x.القسم}</td><td>{x.أيام_الحضور}</td><td>{x.بصمة_واحدة}</td><td>{x.عدد_البصمات}</td></tr>)}</tbody></table></TableWrap></section></>}function Settings({settings,setSettings}:{settings:any;setSettings:Dispatch<SetStateAction<any>>}){const [f,setF]=useState(settings);function save(){setSettings(f);alert('تم حفظ الإعدادات')}return <><PageActions title="الإعدادات" text="مواعيد العمل والنسخ الاحتياطي" action="💾 حفظ" onClick={save}/><section className="panel"><div className="form-grid"><label>بداية العمل<input type="time" value={f.start} onChange={e=>setF({...f,start:e.target.value})}/></label><label>نهاية العمل<input type="time" value={f.end} onChange={e=>setF({...f,end:e.target.value})}/></label><label>سماح التأخير بالدقائق<input type="number" min="0" value={f.grace} onChange={e=>setF({...f,grace:+e.target.value})}/></label><label className="check-field"><input type="checkbox" checked={f.fridayOff!==false} onChange={e=>setF({...f,fridayOff:e.target.checked})}/> اعتبار يوم الجمعة عطلة أسبوعية</label><label className="full">العطلات الرسمية<textarea value={f.holidays} onChange={e=>setF({...f,holidays:e.target.value})}/></label></div><button className="primary-btn" onClick={save}>حفظ الإعدادات</button></section></>}
function PageActions({title,text,action,onClick}:{title:string;text:string;action:string;onClick:()=>void}){return <div className="page-actions"><div><h2>{title}</h2><p>{text}</p></div><button className="primary-btn" onClick={onClick}>{action}</button></div>}
function TableWrap({children}:{children:ReactNode}){return <div className="table-wrap">{children}</div>}
function EmptyRow({col,text}:{col:number;text:string}){return <tr><td colSpan={col}><div className="table-empty">{text}</div></td></tr>}
function Modal({title,close,children}:{title:string;close:()=>void;children:ReactNode}){return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><div className="modal"><div className="modal-head"><h2>{title}</h2><button onClick={close}>×</button></div>{children}</div></div>}
export default App
